JS_INCLUDE = '\n<link rel="stylesheet"\nhref="https://maxcdn.bootstrapcdn.com/font-awesome/4.4.0/css/font-awesome.min.css">\n<script language="javascript">\nfunction is_internet_explorer() {\nua = navigator.user_agent;\n/* MSIE used to detect old browsers and Trident used to newer ones*/\nreturn ua.index_of("MSIE ") > -1 || ua.index_of("Trident/") > -1;\n}\n\n/* Define the Animation class */\nfunction Animation(frames, img_id, slider_id, interval, loop_select_id){\nthis.img_id = img_id;\nthis.slider_id = slider_id;\nthis.loop_select_id = loop_select_id;\nthis.interval = interval;\nthis.current_frame = 0;\nthis.direction = 0;\nthis.timer = null;\nthis.frames = new Array(frames.length);\n\nfor (var i=0; i<frames.length; i++)\n{\nthis.frames[i] = new Image();\nthis.frames[i].src = frames[i];\n}\nvar slider = document.get_element_by_id(this.slider_id);\nslider.max = this.frames.length - 1;\nif (is_internet_explorer()) {\n// switch from oninput to onchange because IE <= 11 does not conform\n// with W3C specification. It ignores oninput and onchange behaves\n// like oninput. In contrast, Microsoft Edge behaves correctly.\nslider.set_attribute(\'onchange\', slider.get_attribute(\'oninput\'));\nslider.set_attribute(\'oninput\', null);\n}\nthis.set_frame(this.current_frame);\n}\n\nAnimation.prototype.get_loop_state = function(){\nvar button_group = document[this.loop_select_id].state;\nfor (var i = 0; i < button_group.length; i++) {\nvar button = button_group[i];\nif (button.checked) {\nreturn button.value;\n}\n}\nreturn undefined;\n}\n\nAnimation.prototype.set_frame = function(frame){\nthis.current_frame = frame;\ndocument.get_element_by_id(this.img_id).src =\nthis.frames[this.current_frame].src;\ndocument.get_element_by_id(this.slider_id).value = this.current_frame;\n}\n\nAnimation.prototype.next_frame = function()\n{\nthis.set_frame(Math.min(this.frames.length - 1, this.current_frame + 1));\n}\n\nAnimation.prototype.previous_frame = function()\n{\nthis.set_frame(Math.max(0, this.current_frame - 1));\n}\n\nAnimation.prototype.first_frame = function()\n{\nthis.set_frame(0);\n}\n\nAnimation.prototype.last_frame = function()\n{\nthis.set_frame(this.frames.length - 1);\n}\n\nAnimation.prototype.slower = function()\n{\nthis.interval /= 0.7;\nif(this.direction > 0){this.play_animation();}\nelse if(this.direction < 0){this.reverse_animation();}\n}\n\nAnimation.prototype.faster = function()\n{\nthis.interval *= 0.7;\nif(this.direction > 0){this.play_animation();}\nelse if(this.direction < 0){this.reverse_animation();}\n}\n\nAnimation.prototype.anim_step_forward = function()\n{\nthis.current_frame += 1;\nif(this.current_frame < this.frames.length){\nthis.set_frame(this.current_frame);\n}else{\nvar loop_state = this.get_loop_state();\nif(loop_state == "loop"){\nthis.first_frame();\n}else if(loop_state == "reflect"){\nthis.last_frame();\nthis.reverse_animation();\n}else{\nthis.pause_animation();\nthis.last_frame();\n}\n}\n}\n\nAnimation.prototype.anim_step_reverse = function()\n{\nthis.current_frame -= 1;\nif(this.current_frame >= 0){\nthis.set_frame(this.current_frame);\n}else{\nvar loop_state = this.get_loop_state();\nif(loop_state == "loop"){\nthis.last_frame();\n}else if(loop_state == "reflect"){\nthis.first_frame();\nthis.play_animation();\n}else{\nthis.pause_animation();\nthis.first_frame();\n}\n}\n}\n\nAnimation.prototype.pause_animation = function()\n{\nthis.direction = 0;\nif (this.timer){\nclear_interval(this.timer);\nthis.timer = null;\n}\n}\n\nAnimation.prototype.play_animation = function()\n{\nthis.pause_animation();\nthis.direction = 1;\nvar t = this;\nif (!this.timer) this.timer = set_interval(function() {\nt.anim_step_forward();\n}, this.interval);\n}\n\nAnimation.prototype.reverse_animation = function()\n{\nthis.pause_animation();\nthis.direction = -1;\nvar t = this;\nif (!this.timer) this.timer = set_interval(function() {\nt.anim_step_reverse();\n}, this.interval);\n}\n</script>\n'
STYLE_INCLUDE = '\n<style>\n.animation {\ndisplay: inline-block;\ntext-align: center;\n}\ninput[type=range].anim-slider {\nwidth: 374px;\nmargin-left: auto;\nmargin-right: auto;\n}\n.anim-buttons {\nmargin: 8px 0px;\n}\n.anim-buttons button {\npadding: 0;\nwidth: 36px;\n}\n.anim-state label {\nmargin-right: 8px;\n}\n.anim-state input {\nmargin: 0;\nvertical-align: middle;\n}\n</style>\n'
DISPLAY_TEMPLATE = '\n<div class="animation">\n<img id="_anim_img{id}">\n<div class="anim-controls">\n<input id="_anim_slider{id}" type="range" class="anim-slider"\nname="points" min="0" max="1" step="1" value="0"\noninput="anim{id}.set_frame(parse_int(this.value));">\n<div class="anim-buttons">\n<button title="Decrease speed" aria-label="Decrease speed" onclick="anim{id}.slower()">\n<i class="fa fa-minus"></i></button>\n<button title="First frame" aria-label="First frame" onclick="anim{id}.first_frame()">\n<i class="fa fa-fast-backward"></i></button>\n<button title="Previous frame" aria-label="Previous frame" onclick="anim{id}.previous_frame()">\n<i class="fa fa-step-backward"></i></button>\n<button title="Play backwards" aria-label="Play backwards" onclick="anim{id}.reverse_animation()">\n<i class="fa fa-play fa-flip-horizontal"></i></button>\n<button title="Pause" aria-label="Pause" onclick="anim{id}.pause_animation()">\n<i class="fa fa-pause"></i></button>\n<button title="Play" aria-label="Play" onclick="anim{id}.play_animation()">\n<i class="fa fa-play"></i></button>\n<button title="Next frame" aria-label="Next frame" onclick="anim{id}.next_frame()">\n<i class="fa fa-step-forward"></i></button>\n<button title="Last frame" aria-label="Last frame" onclick="anim{id}.last_frame()">\n<i class="fa fa-fast-forward"></i></button>\n<button title="Increase speed" aria-label="Increase speed" onclick="anim{id}.faster()">\n<i class="fa fa-plus"></i></button>\n</div>\n<form title="Repetition mode" aria-label="Repetition mode" action="#n" name="_anim_loop_select{id}"\nclass="anim-state">\n<input type="radio" name="state" value="once" id="_anim_radio1_{id}"\n{once_checked}>\n<label for="_anim_radio1_{id}">Once</label>\n<input type="radio" name="state" value="loop" id="_anim_radio2_{id}"\n{loop_checked}>\n<label for="_anim_radio2_{id}">Loop</label>\n<input type="radio" name="state" value="reflect" id="_anim_radio3_{id}"\n{reflect_checked}>\n<label for="_anim_radio3_{id}">Reflect</label>\n</form>\n</div>\n</div>\n\n\n<script language="javascript">\n/* Instantiate the Animation class. */\n/* The IDs given should match those used in the template above. */\n(function() {{\nvar img_id = "_anim_img{id}";\nvar slider_id = "_anim_slider{id}";\nvar loop_select_id = "_anim_loop_select{id}";\nvar frames = new Array({Nframes});\n{fill_frames}\n\n/* set a timeout to make sure all the above elements are created before\nthe object is initialized. */\nset_timeout(function() {{\nanim{id} = new Animation(frames, img_id, slider_id, {interval},\nloop_select_id);\n}}, 0);\n}})()\n</script>\n'
INCLUDED_FRAMES = '\nfor (var i=0; i<{Nframes}; i++){{\nframes[i] = "{frame_dir}/frame" + ("0000000" + i).slice(-7) +\n".{frame_format}";\n}}\n'